#!/usr/bin/env node
// Build the minified third-party JavaScript in data/static/js from the
// unmodified upstream sources in this directory.
//
// Usage (from this directory):
//
//     npm ci
//     npm run build    # regenerate the files in data/static/js
//     npm run check    # fail if they are out of date
//
// See README.md for where each source file came from.

'use strict';

const fs = require('fs');
const path = require('path');
const { minify } = require('terser');

const vendorDir = __dirname;
const outDir = path.join(vendorDir, '..', 'data', 'static', 'js');

const targets = [
  {
    output: 'jquery-4.0.0.min.js',
    sources: ['jquery-4.0.0/dist/jquery.js'],
  },
  {
    // The parts of jQuery UI that gitit uses (draggable and droppable, for
    // dragdiff.js) and their dependencies, in dependency order. The list
    // follows the define() dependencies at the top of each module.
    output: 'jquery-ui-1.14.2.custom.min.js',
    sources: [
      'jquery-ui-1.14.2/ui/version.js',
      'jquery-ui-1.14.2/ui/widget.js',
      'jquery-ui-1.14.2/ui/data.js',
      'jquery-ui-1.14.2/ui/plugin.js',
      'jquery-ui-1.14.2/ui/scroll-parent.js',
      'jquery-ui-1.14.2/ui/widgets/mouse.js',
      'jquery-ui-1.14.2/ui/widgets/draggable.js',
      'jquery-ui-1.14.2/ui/widgets/droppable.js',
    ],
  },
  {
    output: 'jquery.hotkeys-0.2.2.min.js',
    // The upstream copyright comment doesn't use /*! so the minifier would
    // drop it.
    banner: '/*! jQuery Hotkeys Plugin v0.2.2 | https://github.com/jeresig/jquery.hotkeys\n' +
            ' * Copyright 2010, John Resig | Dual licensed under the MIT or GPL Version 2 licenses. */',
    sources: ['jquery-hotkeys-0.2.2/jquery-hotkeys.js'],
  },
];

function readSource(file) {
  // Normalise line endings so a Windows checkout builds identical output.
  return fs.readFileSync(path.join(vendorDir, file), 'utf8').replace(/\r\n/g, '\n');
}

async function build(target) {
  const code = target.sources.map(readSource).join('\n');
  const generated = '/* Generated by vendor/build.js from ' +
                    target.sources.map((s) => 'vendor/' + s).join(', ') +
                    '. Do not edit. */';
  const preamble = [generated, target.banner].filter(Boolean).join('\n');
  const result = await minify(code, {
    compress: true,
    mangle: true,
    format: { comments: /^!/, preamble },
  });
  return result.code + '\n';
}

async function main() {
  const check = process.argv.includes('--check');
  let stale = 0;

  for (const target of targets) {
    const outFile = path.join(outDir, target.output);
    const code = await build(target);
    if (check) {
      const existing = fs.existsSync(outFile) ? fs.readFileSync(outFile, 'utf8') : null;
      if (existing !== code) {
        console.error(`out of date: data/static/js/${target.output}`);
        stale++;
      }
    } else {
      fs.writeFileSync(outFile, code);
      console.log(`wrote data/static/js/${target.output}`);
    }
  }

  if (stale > 0) {
    console.error('Run `npm run build` in vendor/ to regenerate.');
    process.exit(1);
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
